import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv3d_kh_kw_forward(torch::Tensor x,
                                    torch::Tensor w,
                                    c10::optional<torch::Tensor> b,
                                    int stride, int padding, int dilation, int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Cooperative tiled direct 3D convolution (kernel size kH x kW x kD, general stride/padding/dilation/groups).
// Designed for the case kD is small (here typically 1) so the "depth" dimension is handled by an
// extra grid dimension while (H, W) receive the tiled cooperative treatment.

template <typename T>
__global__ __launch_bounds__(256, 4) void conv3d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ Bias,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win, int D,
    int Cout, int Cin_per_group, int Cout_per_group, int groups,
    int kH, int kW, int kD,
    int stride, int padding, int dilation,
    int Hout, int Wout, int Dout,
    int oc_per_block,
    int patchH, int patchW)
{
  constexpr int TILE_OH = 16;
  constexpr int TILE_OW = 16;
  constexpr int Threads = TILE_OH * TILE_OW;
  constexpr int MAX_OC  = 8;
  constexpr int DTILE   = 4;
  constexpr int PATCH_PAD = 1;
  constexpr int PATCH_STRIDE = DTILE + PATCH_PAD;
  extern __shared__ unsigned char smem_raw[];
  const int patchSize     = patchH * patchW;
  const int patchTileSize = patchSize * DTILE;
  const int patchTileSizePadded = patchSize * PATCH_STRIDE;
  const int weightSize    = MAX_OC * kH * kW;
  T* sX[2];
  T* sW[2];
  sX[0] = reinterpret_cast<T*>(smem_raw);
  sW[0] = reinterpret_cast<T*>(smem_raw + (size_t)patchTileSizePadded * sizeof(T));
  sX[1] = reinterpret_cast<T*>(smem_raw + (size_t)(patchTileSizePadded + weightSize) * sizeof(T));
  sW[1] = reinterpret_cast<T*>(smem_raw + (size_t)(2 * patchTileSizePadded + weightSize) * sizeof(T));
  const int tid = threadIdx.x;
  const int local_oh = tid / TILE_OW;
  const int local_ow = tid % TILE_OW;
  const int Dout_tiles = (Dout + DTILE - 1) / DTILE;
  const int n_odt = blockIdx.z;
  const int n     = n_odt / Dout_tiles;
  const int odt   = n_odt % Dout_tiles;
  const int od_base = odt * DTILE;
  const int oc_base  = blockIdx.y * oc_per_block;
  const int group    = oc_base / Cout_per_group;
  const int cin_start = group * Cin_per_group;
  const int n_tiles_w  = (Wout + TILE_OW - 1) / TILE_OW;
  const int tile_idx    = blockIdx.x;
  const int tile_oh_idx = tile_idx / n_tiles_w;
  const int tile_ow_idx = tile_idx % n_tiles_w;
  const int oh_base = tile_oh_idx * TILE_OH;
  const int ow_base = tile_ow_idx * TILE_OW;
  const int oh = oh_base + local_oh;
  const int ow = ow_base + local_ow;
  const bool valid_out = (oh < Hout) && (ow < Wout);
  const int64_t sXc = (int64_t)H * Win * D;
  const int64_t sXh = (int64_t)Win * D;
  const int64_t sXw = (int64_t)D;
  const int64_t sYc = (int64_t)Hout * Wout * Dout;
  const int64_t sYh = (int64_t)Wout * Dout;
  const int64_t sYw = (int64_t)Dout;
  const int64_t sWo = (int64_t)Cin_per_group * kH * kW * kD;
  const int64_t sWc = (int64_t)kH * kW * kD;
  const int64_t sWh = (int64_t)kW * kD;
  const int64_t sXn = (int64_t)Cin * H * Win * D;
  const int64_t sYn = (int64_t)Cout * Hout * Wout * Dout;
  const T* Xn = X + (int64_t)n * sXn;
  T* Yn       = Y + (int64_t)n * sYn;
  const int ih0 = oh_base * stride - padding;
  const int iw0 = ow_base * stride - padding;
  float acc[MAX_OC][DTILE];
  #pragma unroll
  for (int oc_l = 0; oc_l < MAX_OC; ++oc_l) {
    int oc = oc_base + oc_l;
    float bval = 0.0f;
    if (oc_l < oc_per_block && oc < Cout && Bias != nullptr) bval = (float)Bias[oc];
    #pragma unroll
    for (int dd = 0; dd < DTILE; ++dd) acc[oc_l][dd] = bval;
  }
  const int totalIters = Cin_per_group * kD;
  auto load_stage = [&] (int buf, int iter) {
    int cin_off = iter / kD;
    int kd_i    = iter - cin_off * kD;
    int cin = cin_start + cin_off;
    T* sXb = sX[buf];
    T* sWb = sW[buf];
    for (int c = tid; c < patchTileSize; c += Threads) {
      int idx = c / DTILE;
      int dd  = c - idx * DTILE;
      int ph = idx / patchW;
      int pw = idx - ph * patchW;
      int od = od_base + dd;
      bool od_valid = od < Dout;
      int id = od * stride - padding + kd_i * dilation;
      bool id_valid = od_valid && ((unsigned)id < (unsigned)D);
      int ih = ih0 + ph;
      int iw = iw0 + pw;
      T val = T(0);
      if (id_valid && (unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)Win) {
        val = Xn[(int64_t)cin * sXc + (int64_t)ih * sXh + (int64_t)iw * sXw + id];
      }
      sXb[idx * PATCH_STRIDE + dd] = val;
    }
    for (int idx = tid; idx < weightSize; idx += Threads) {
      int oc_l = idx / (kH * kW);
      int kk   = idx - oc_l * (kH * kW);
      int kh_i = kk / kW;
      int kw_i = kk - kh_i * kW;
      T wval = T(0);
      if (oc_l < oc_per_block) {
        int oc = oc_base + oc_l;
        if (oc < Cout) {
          wval = W[(int64_t)oc * sWo + (int64_t)cin_off * sWc + (int64_t)kh_i * sWh + (int64_t)kw_i * kD + kd_i];
        }
      }
      sWb[idx] = wval;
    }
  };
  if (totalIters > 0) {
    load_stage(0, 0);
    __syncthreads();
    for (int iter = 0; iter < totalIters; ++iter) {
      int cur = iter & 1;
      int nxt = (iter + 1) & 1;
      if (iter + 1 < totalIters) {
        load_stage(nxt, iter + 1);
      }
      if (valid_out) {
        T* sXb = sX[cur];
        T* sWb = sW[cur];
        for (int kh_i = 0; kh_i < kH; ++kh_i) {
          int ph = local_oh * stride + kh_i * dilation;
          for (int kw_i = 0; kw_i < kW; ++kw_i) {
            int pw = local_ow * stride + kw_i * dilation;
            int idx = ph * patchW + pw;
            float wvals[MAX_OC];
            #pragma unroll
            for (int oc_l = 0; oc_l < MAX_OC; ++oc_l) {
              if (oc_l >= oc_per_block) break;
              wvals[oc_l] = (float)sWb[oc_l * kH * kW + kh_i * kW + kw_i];
            }
